import { RTKWrapper } from '06_shared/components/RTKWrapper/RTKWrapper';
import { userApi, useGetWebsocketToken } from '05_entities/user';
import { useEffect } from 'react';
import { useAppDispatch } from '06_shared/hooks/useAppDispatch';
import { websocketTransport } from '06_shared/lib/websocket';
import { notificationActions } from '05_entities/notification';
import { NOTIFICATION_KEYS } from '06_shared/constants/notificationKeys';
// Тонкий bootstrap транспорту: єдина задача — підняти й закрити
// зʼєднання. Доменні підписки живуть у своїх сутностях, тож їхній код
// їде в лінивих чанках тих, хто ці дані показує, а не завжди.
const WebsocketLoader = () => {
    const dispatch = useAppDispatch();
    const websocket_token = useGetWebsocketToken();
    useEffect(() => {
        if (!websocket_token)
            return;
        websocketTransport.connect(`${__WS_URL__}/ws-core/${websocket_token}`);
        return () => {
            websocketTransport.disconnect();
        };
    }, [websocket_token]);
    useEffect(() => {
        const unsubscribeOpen = websocketTransport.onOpen(() => {
            dispatch(notificationActions.addNotificationItem({
                type: 'Success',
                description: [NOTIFICATION_KEYS.WEBSOCKET_CONNECTED],
            }));
        });
        const unsubscribeClose = websocketTransport.onClose(() => {
            dispatch(notificationActions.addNotificationItem({
                type: 'Information',
                description: [NOTIFICATION_KEYS.WEBSOCKET_CLOSED],
            }));
        });
        const unsubscribeError = websocketTransport.onError(() => {
            dispatch(notificationActions.addNotificationItem({
                type: 'Error',
                description: [NOTIFICATION_KEYS.WEBSOCKET_ERROR],
            }));
        });
        return () => {
            unsubscribeOpen();
            unsubscribeClose();
            unsubscribeError();
        };
    }, [dispatch]);
    return null;
};
export default RTKWrapper(WebsocketLoader, [userApi], {}, false, null);
